//! Cargo-driven `gdiplus.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x785f0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff84000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff84000000u64)),
        o => panic!("gdiplus-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "import:windowscodecs", "import:mlang", "import:msvcrt", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:gdi32", "import:kernel32", "import:kernel32_vista", "import:ntdll", "import:ntdll_vista", "engine:delayimp_rust", "body", "engine:oldnames"],
        "x86_64" => &["engine:wine", "import:windowscodecs", "import:mlang", "import:msvcrt", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:gdi32", "import:kernel32", "import:kernel32_vista", "import:ntdll", "import:ntdll_vista", "engine:delayimp_rust", "body", "engine:oldnames"],
        "aarch64" => &["engine:wine", "import:windowscodecs", "import:mlang", "import:msvcrt", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:gdi32", "import:kernel32", "import:kernel32_vista", "import:ntdll", "import:ntdll_vista", "engine:delayimp_rust", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/gdiplus",
        "dll/win32/gdiplus",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_USE_MATH_DEFINES",
        "_WIN32_WINNT=0x601",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
        "wcsicmp=_wcsicmp",
    ];

    Linker::new(target_json)
        .c_from_compile_db("gdiplus_shims", &["dll/win32/gdiplus/brush.c", "dll/win32/gdiplus/customlinecap.c", "dll/win32/gdiplus/font.c", "dll/win32/gdiplus/gdiplus.c", "dll/win32/gdiplus/graphics.c", "dll/win32/gdiplus/graphicspath.c", "dll/win32/gdiplus/image.c", "dll/win32/gdiplus/imageattributes.c", "dll/win32/gdiplus/matrix.c", "dll/win32/gdiplus/metafile.c", "dll/win32/gdiplus/pathiterator.c", "dll/win32/gdiplus/pen.c", "dll/win32/gdiplus/region.c", "dll/win32/gdiplus/stringformat.c", "dll/win32/gdiplus/guid.c"])
        .rc("dll/win32/gdiplus/gdiplus.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/gdiplus/gdiplus.spec", "gdiplus.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/windowscodecs/windowscodecs.spec", "windowscodecs.dll", "windowscodecs")
        .import_lib("dll/win32/mlang/mlang.spec", "mlang.dll", "mlang")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/ntdll/nt_0600/ntdll_vista.spec", "ntdll_vista.dll", "ntdll_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
